def utc_iso8601(timestamp: float) -> str:
    """Render a Unix timestamp as a stable UTC ISO-8601 value."""
    return datetime.fromtimestamp(timestamp, timezone.utc).isoformat().replace("+00:00", "Z")


def active_model_cooldowns(
    value: Any, current_time: Optional[float] = None
) -> Tuple[dict[Any, float], int]:
    """Return active numeric cooldowns and the number of malformed values ignored."""
    if value in (None, "", b""):
        return {}, 0
    if isinstance(value, bytes):
        try:
            value = value.decode("utf-8")
        except UnicodeDecodeError:
            return {}, 1
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except (TypeError, ValueError):
            return {}, 1
    if not isinstance(value, dict):
        return {}, 1

    now = time.time() if current_time is None else current_time
    active: dict[Any, float] = {}
    invalid_count = 0
    for model_name, deadline in value.items():
        if isinstance(deadline, bool) or not isinstance(deadline, (int, float)):
            invalid_count += 1
            continue
        if deadline > now:
            active[model_name] = deadline
    return active, invalid_count

if mode == "antigravity":
    model_cooldowns, close_cycle = prepare_antigravity_cooldown(
        model_cooldowns, model_name, cooldown_until
    )
elif cooldown_until is None:
    model_cooldowns.pop(model_name, None)
else:
    previous_until = model_cooldowns.get(model_name)
    model_cooldowns[model_name] = cooldown_until
    close_cycle = not previous_until or previous_until <= time.time()

# 设置模型级冷却
if cooldown_until is not None and model_name:
    if hasattr(self._storage_adapter._backend, 'set_model_cooldown'):
        await self._storage_adapter._backend.set_model_cooldown(
            credential_name, model_name, cooldown_until, mode=mode
        )
        log.info(
            f"设置模型级冷却: {_credential_label(credential_name, mode)}, model_name={model_name}, "
            f"冷却至: {datetime.fromtimestamp(cooldown_until, timezone.utc).isoformat()}"
        )

now = time.time()
def _resolve_cooldown_until_for_model(quota_entry: dict) -> float:
    # 优先用 Google 给的 resetTimeRaw，必须是未来时间且非 epoch 0
    from datetime import datetime as _dt
    raw = quota_entry.get("resetTimeRaw") or ""
    if raw:
        try:
            iso = raw.replace("Z", "+00:00")
            ts = _dt.fromisoformat(iso).timestamp()
            if ts > now + 60:
                return ts
        except Exception:
            pass
    return now + fallback_cooldown_seconds
